// 从 AI 响应中提取单词列表
const aiResponse = $input.item.json.response || $input.item.json;
let selectedWords;

// 尝试解析 AI 的响应
try {
  let parsed;
  if (typeof aiResponse === 'string') {
    parsed = JSON.parse(aiResponse);
  } else {
    parsed = aiResponse;
  }

  selectedWords = parsed.selected;

  if (!Array.isArray(selectedWords)) {
    throw new Error('Selected words is not an array');
  }

} catch (error) {
  console.error('Failed to parse AI response:', error);
  // 如果解析失败，使用候选词的前8个
  const candidates = $input.item.json.candidates || [];
  selectedWords = candidates.slice(0, 8);
}

// 验证单词数量
if (selectedWords.length !== 8) {
  throw new Error(`Expected 8 words, got ${selectedWords.length}`);
}

// 转换为小写并清理
selectedWords = selectedWords.map(w => w.toLowerCase().trim());

// 计算明天的日期
const tomorrow = new Date();
tomorrow.setDate(tomorrow.getDate() + 1);
const dateStr = tomorrow.toISOString().split('T')[0];

// 返回用于下一步的数据
return {
  json: {
    answers: selectedWords,
    date: dateStr,
    gameType: 'octordle',
    language: 'en',
    regenerate: false,
    aiReasoning: aiResponse.reasoning || 'N/A',
    aiRejected: aiResponse.rejected || []
  }
};

